CREATE TABLE IF NOT EXISTS visa_case_events (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL REFERENCES travel_orders(id) ON DELETE CASCADE,event_type TEXT NOT NULL,old_status TEXT,new_status TEXT,message TEXT,visibility TEXT NOT NULL DEFAULT 'customer' CHECK(visibility IN ('customer','internal')),actor_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS visa_case_documents (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL REFERENCES travel_orders(id) ON DELETE CASCADE,document_type TEXT NOT NULL DEFAULT 'other',original_name TEXT NOT NULL,stored_name TEXT NOT NULL UNIQUE,mime_type TEXT NOT NULL,file_size INTEGER NOT NULL CHECK(file_size BETWEEN 1 AND 15728640),sha256 TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected')),reviewer_note TEXT,uploaded_by TEXT NOT NULL DEFAULT 'customer' CHECK(uploaded_by IN ('customer','admin')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,reviewed_at TEXT);
CREATE INDEX IF NOT EXISTS idx_visa_case_events_order ON visa_case_events(order_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_visa_case_documents_order ON visa_case_documents(order_id,status,created_at DESC);
